# AST: Obj::SetOperator::Intersect
# Run: target/release/litex -f examples/test_objs/intersect.lit
# Cases use discarded sketch scopes; no cross-case facts.

# P01: intersect({1, 2}, {2, 3}) = {2}
sketch:
    by extension:
        ? intersect({1, 2}, {2, 3}) = {2}
        claim:
            ? forall x intersect({1, 2}, {2, 3}):
                x $in {2}
            x $in {1, 2}
            x $in {2, 3}
            x = 1 or x = 2
            by cases:
                ? x $in {2}
                case x = 1:
                    1 $in {2, 3}
                    impossible 1 $in {2, 3}
                case x = 2:
                    x $in {2}
        forall x {2}:
            x $in intersect({1, 2}, {2, 3})

# P02: intersect({}, {1}) = {}
sketch:
    intersect({}, {1}) = {}

# P03: intersect({1}, {1}) = {1}
sketch:
    intersect({1}, {1}) = {1}

# P04: 2 $in intersect({1, 2}, {2, 3})
sketch:
    2 $in intersect({1, 2}, {2, 3})

# P05: not 1 $in intersect({1, 2}, {2, 3})
sketch:
    not 1 $in intersect({1, 2}, {2, 3})

# P06: intersect(A, B) = intersect(B, A)
sketch:
    forall A, B set:
        intersect(A, B) = intersect(B, A)

# AST: Obj::SetOperator::SetMinus
# Run: target/release/litex -f examples/test_objs/set_minus.lit
# Cases use discarded sketch scopes; no cross-case facts.

# P01: set_minus({1, 2}, {2}) = {1}
sketch:
    by extension:
        ? set_minus({1, 2}, {2}) = {1}
        claim:
            ? forall x set_minus({1, 2}, {2}):
                x $in {1}
            x $in {1, 2}
            not x $in {2}
            x = 1 or x = 2
            by cases:
                ? x $in {1}
                case x = 1:
                    x $in {1}
                case x = 2:
                    not 2 $in {2}
                    impossible not 2 $in {2}
        forall x {1}:
            x $in set_minus({1, 2}, {2})

# P02: set_minus({1}, {}) = {1}
sketch:
    set_minus({1}, {}) = {1}

# P03: set_minus({}, {1}) = {}
sketch:
    set_minus({}, {1}) = {}

# P04: set_minus({1}, {1}) = {}
sketch:
    set_minus({1}, {1}) = {}

# P05: 1 $in set_minus({1, 2}, {2})
sketch:
    1 $in set_minus({1, 2}, {2})

# P06: not 2 $in set_minus({1, 2}, {2})
sketch:
    not 2 $in set_minus({1, 2}, {2})

# AST: Obj::SetFormer::ListSet
# Run: target/release/litex -f examples/test_objs/list_set.lit
# Cases use discarded sketch scopes; no cross-case facts.

# P01: finite_set_size({}) = 0
sketch:
    finite_set_size({}) = 0

# P02: 1 $in {1, 2}
sketch:
    1 $in {1, 2}

# P03: not 3 $in {1, 2}
sketch:
    not 3 $in {1, 2}

# P04: {1, 2} = {2, 1}
sketch:
    by extension {1, 2} = {2, 1}

# P05: finite_set_size({1, 2}) = 2
sketch:
    finite_set_size({1, 2}) = 2

# P06: {1} $in {{1}, {2}}
sketch:
    by contra:
        ? {1} != {2}
        1 $in {1}
        1 $in {2}
        impossible 1 $in {2}
    {1} $in {{1}, {2}}

# P07: (1, 2) $in {(1, 2), (2, 1)}
sketch:
    by contra:
        ? (1, 2) != (2, 1)
        1 = (1, 2)[1] = (2, 1)[1] = 2
        impossible 1 = 2
    (1, 2) $in {(1, 2), (2, 1)}

# P08: $is_finite_set({})
sketch:
    $is_finite_set({})

# AST: Obj::SetFormer::Range
# Run: target/release/litex -f examples/test_objs/range.lit
# Cases use discarded sketch scopes; no cross-case facts.

# P01: range(1, 3) = {1, 2}
sketch:
    range(1, 3) = {1, 2}

# P02: range(2, 2) = {}
sketch:
    range(2, 2) = {}

# P03: range(3, 1) = {}
sketch:
    range(3, 1) = {}

# P05: 1 $in range(1, 3)
sketch:
    1 $in range(1, 3)

# P07: finite_set_size(range(0, 3)) = 3
sketch:
    finite_set_size(range(0, 3)) = 3

